import sys, random, json
sys.path.insert(0,'/workspace/project')
import main as impl
import refclient

def rand_frames(rng):
    frames = []
    for _ in range(rng.randint(0, 6)):
        kind = rng.choice(['headers','data','datagram','sleep'])
        if kind == 'headers':
            frames.append({'Type':'headers','data_to_transfered':[[':method','GET'],[':path','/'+str(rng.randint(0,9))]],
                           'End_Stream':rng.random()<0.5})
        elif kind in ('data','datagram'):
            frames.append({'Type':kind,'data_to_transfered':'d'*rng.randint(0,3),'End_Stream':rng.random()<0.5})
        else:
            frames.append({'Type':'sleep','Time_to_Stop':rng.choice([0,0,1,2,5])})
    return frames

def rand_event(rng, ncases):
    kind = rng.choice(['headers','data','close','headers','data'])
    at = rng.choice([0,0,1,2,3,5,6,10])
    if kind == 'close':
        return {'at':at,'kind':'close'}
    stream = rng.choice([0,4,8,2,7]) if ncases else 0
    if kind == 'headers':
        return {'at':at,'kind':'headers','stream':stream,'fields':[[':status','200']],'end':rng.random()<0.6}
    return {'at':at,'kind':'data','stream':stream,'data':'x'*rng.randint(0,2),'end':rng.random()<0.6}

def run(doc):
    try:
        return impl.run(doc)
    except Exception:
        return {'error':'input'}

bad = 0
count = int(sys.argv[1]) if len(sys.argv)>1 else 500
for seed in range(count):
    rng = random.Random(seed)
    ncases = rng.randint(0, 3)
    cases = []
    for i in range(ncases):
        cases.append({'name':'c%d'%i,'frames':rand_frames(rng),
                      'expect':{'method':'GET','target':'/','host':'h'}})
    events = [rand_event(rng, ncases) for _ in range(rng.randint(0,4))]
    timeout = rng.choice([1,5,10])
    doc = {'seed':'s','definitions':[],'timeout_ms':timeout,'cases':cases,'events':events,'channels':[]}
    out = run(doc)
    if 'error' in out:
        print('INPUT ERROR seed', seed); bad += 1; continue
    # reference
    frames = []
    for case in cases:
        fl = []
        for f in case['frames']:
            if f['Type'] == 'headers':
                fl.append({'Type':'headers','End_Stream':f['End_Stream'],
                           'data_to_transfered':[(n.encode(), v.encode()) for n,v in f['data_to_transfered']]})
            elif f['Type'] in ('data','datagram'):
                fl.append({'Type':f['Type'],'End_Stream':f['End_Stream'],'data_to_transfered':f['data_to_transfered'].encode()})
            else:
                fl.append({'Type':'sleep','Time_to_Stop':f['Time_to_Stop']})
        frames.append(fl)
    evs = []
    for e in events:
        if e['kind'] == 'close':
            evs.append({'at':e['at'],'kind':'close'})
        elif e['kind'] == 'headers':
            evs.append({'at':e['at'],'kind':'headers','stream':e['stream'],'end':e['end'],
                        'fields':[(n.encode(), v.encode()) for n,v in e['fields']]})
        else:
            evs.append({'at':e['at'],'kind':'data','stream':e['stream'],'end':e['end'],'data':e['data'].encode()})
    ref = refclient.simulate(frames, evs, timeout)
    for got, r in zip(out['cases'], ref):
        for key in ('state','at','frames','request_frames','payload_bytes','sent','received','response_frames','response_body'):
            if got[key] != r[key]:
                print('MISMATCH seed', seed, key, got[key], r[key])
                print('  cases', json.dumps(cases))
                print('  events', json.dumps(events))
                bad += 1
                break
        if bad > 3: break
    if bad > 3: break
print('done, failures:', bad)
